// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CameraPolicy) predicate.CameraPolicy {
	return predicate.CameraPolicy(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CameraPolicy) predicate.CameraPolicy {
	return predicate.CameraPolicy(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CameraPolicy) predicate.CameraPolicy {
	return predicate.CameraPolicy(sql.NotPredicates(p))
}
